(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hr"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Natrag na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Prebaci između svijetle i tamne teme","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","words.underline":"Podcrtaj ove riječi na stranici","words.underlineHelp":"Prijeđi mišem preko riječi s točkastom crtom ili je dodirni da vidiš što znači.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj ploči","index.description":"AI-gile je kanban ploča za AI timove koji programiraju. Rade dok ti spavaš; tebi ostaje jedna kratka hrpa stvari koje trebaš odlučiti, testirati i prihvatiti.","hero.logoAlt":"Ikona AI-gile ploče","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;ploči.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano je i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Budiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klikneš, prihvatiš, vratiš se kavi.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali timu ne treba stand-up kava. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi duljinu, od jedne riječi do 144. Svaka duljina ima svoj opis, napisan baš za tu veličinu. Povuci klizač ili koristi strelice.","pitch.rangeLabel":"Duljina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na ploči upravo sada","count.line.html.other":"{n} kartica na ploči upravo sada","features.aria":"Što radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> sadrži sve što čeka tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može obaviti samo čovjek. Tvoj red kaže što je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentiraj karticu i tim se budi, odradi posao i vrati je s koracima koje može pratiti i umoran čovjek.","f.tester.h":"AI tester provjerava prvi","f.tester.p":"Prije nego išta stigne do tebe, tester prati korake u kopiji aplikacije i pokazuje što je vidio, sa snimkom zaslona. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, ne obećanja","f.proof.p":"Svaka primopredaja pokazuje što se promijenilo: datoteke, diff, snimke zaslona. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Razgovaraj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, s gumbom ✅ Go.","f.tidy.h":"Sam se uredi","f.tidy.p":"Povezane kartice stapaju se u jednu, zbrkani naslovi se ispravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih se prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računalu","f.private.li1":"Ploča radi na tvom računalu i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima šifrirane su od kraja do kraja.","f.private.li3":"Bez računa, bez tragača, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Više od 120 jezika, od nizozemskog, velškog i japanskog do gusarskog, Yode i klingonskog, s brzim povratkom na engleski za razvojničke riječi.","tl.aria":"Vremenska crta od prvog razgovora do plana","tl.h2":"Od prvog razgovora do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Nakon današnjeg dana to je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan mali čovjek i velik broj strpljivih agenata. Zasad je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Javit ćemo ti se e-poštom, ništa više","footer.tag":"AI-gile. Bez tragača, bez kolačića, bez stand-up kave.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Što čuvamo","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovno kasnije.","form.offline":"Nije moguće doći do AI-gilea: pokušaj ponovno kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a zatim brišemo. Bez tragača, bez kolačića.","form.keepLink":"Što čuvamo","interest.title":"AI-gile: javi mi kad se alfa otvori","interest.description":"Ostavi e-adresu da saznaš kad se otvori zatvorena alfa ili beta AI-gilea.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-adresu i javit ćemo se jednom, kad bude mjesta za tebe.","interest.email":"Tvoja e-adresa","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, puno promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Svejedno, što prije dođe","interest.submit":"Stavi me na popis","interest.thanks":"Hvala! Na popisu si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš AI-gile u poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš AI-gile na poslu? Reci nam tko si i čime se baviš. Ako donosi nešto dobro, licenca je besplatna.","licence.company":"Tvrtka","licence.website":"Web-stranica","licence.what":"Čime se baviš","licence.how":"Kako to pomaže svijetu","licence.email":"E-adresa","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-poštom.","status.title":"Status AI-gilea","status.h1":"Status AI-gilea","status.quiet":"Sve je mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web-stranicu, dijeljenje ploča, pozive i preuzimanje.","status.up":"Radi (odgovor stigao za {ms} ms)","status.slow":"Bez odgovora na zadnju provjeru, pokušavam ponovno","status.down":"Ne radi: bez odgovora na zadnje dvije provjere","status.svc.web":"Web-stranica","status.svc.web.offers":"Ova stranica: što je AI-gile i obrazac za prijavu interesa","status.svc.boards":"Dijeljenje ploča","status.svc.boards.offers":"Javne ploče, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje zaslona u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Instalacijski program za Windows i poveznice pozivnica","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do statusne usluge (pokušavam ponovno)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: što čuvamo","privacy.h1":"Što čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, poput tvoje e-adrese. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš poslužitelj ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Otvoriti ga može samo naša vlastita ploča.","privacy.server":"Briše se s poslužitelja čim stigne na našu ploču. Sve što je ondje i nakon 30 dana svejedno se briše.","privacy.board":"Na našoj ploči čuvamo ga samo dok ti ne odgovorimo, a onda ga brišemo i ondje.","privacy.none":"Bez tragača, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane prije? Odgovori na našu poruku e-pošte i javi nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Zadnja kartica premještena upravo sada","live.last.min.one":"Zadnja kartica premještena prije {n} min","live.last.min.other":"Zadnja kartica premještena prije {n} min","live.last.hour.one":"Zadnja kartica premještena prije {n} sat","live.last.hour.other":"Zadnja kartica premještena prije {n} sati","live.last.day.one":"Zadnja kartica premještena prije {n} dan","live.last.day.other":"Zadnja kartica premještena prije {n} dana","live.offline":"Ploča uživo malo odmara. Svratite uskoro.","live.cols":"Backlog|Na redu|U tijeku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na ploči upravo sada","tl.cards.few":"{n} kartice"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Kanban robota.","Agenti, posloženi.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju značajke.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban ploča koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo ludo."]},{"n":8,"texts":["Besplatna kanban ploča na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvaćaš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban ploča na tvom računalu, a kartice preuzimaju AI agenti i rade ih.","Napiši ideju. Tim agenata je izgradi. Tester je provjeri prije tebe.","Besplatno, bez računa, bez tragača: ploča, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban ploča za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvaćaš.","Svaki projekt dobiva lead i tim AI agenata. Komentiraj bilo koju karticu i tim odmah kreće raditi.","Besplatna osobna ploča zadataka koja radi na tvom računalu. Radnici su roboti. Onaj koji kaže da si ti."]},{"n":34,"texts":["Ideje stavljaš na ploču. Tim AI agenata pretvara ih u značajke koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa ne vrijedi kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban ploča koju je Rich izgradio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računalu i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban ploču sa stupcima od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj palac gore."]},{"n":55,"texts":["AI-gile je kanban ploča na kojoj je tim sastavljen od AI agenata. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je značajka gotova, AI tester je isproba i snimi zaslon, a zatim stiže na tvoju hrpu. Prihvati je ili komentiraj pa je prerade.","Počelo je kao jedan način da jedna osoba prati mnogo AI programerskih sesija odjednom, a preraslo je u pravu ploču. Radi na tvom računalu, ne traži račun i nema tragača. Besplatna je za prijatelje i svakoga tko je znatiželjan. Također je nedovršena, pa očekuj grube rubove i poneko iznenađenje.","Evo poštene verzije, bez uljepšavanja. I dalje ti moraš imati ideje i provjeravati rezultate. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentiraš, pokazuje točno što se promijenilo, tko je to napravio i sve to drži na jednoj kratkoj hrpi za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban ploča koju pokrećeš na vlastitom računalu. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan te pomoćnike koji preuzimaju kartice po prioritetu. Kad je nešto izgrađeno, AI tester prati korake testiranja i pokazuje ti što je vidio. Zatim sve čeka na jednoj hrpi nazvanoj Za tebe. Prihvatiš to ili komentiraš pa tim pokuša ponovno. Ništa ne stiže u Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćni čuvar dopunjuje stupac Na redu dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ovaj tjedan, a način bez tokena kaže im da prestanu trošiti. Možeš slati poruke prijateljima, a privatne poruke šifrirane su od kraja do kraja. Ploča govori oko 120 jezika, uključujući nizozemski, flamanski, gusarski i klingonski. Sve je besplatno, a nitko ti to ne pokušava ni prodati.","AI-gile je mali osobni projekt, a ne tvrtka. Rich je želio brinuti o nekoliko AI projekata bez otvaranja svake aplikacije da provjeri stanje, pa su on i agenti izgradili ploču za to, a zatim su tu ploču koristili za gradnju ostatka sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šačicu prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš se javiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban ploča za jednog čovjeka i mnogo AI agenata. Radi na tvom računalu i potpuno je besplatna, bez računa i bez ikakvih tragača, a tvoji podaci ostaju kod tebe. Dodaješ projekte, a svaki projekt dobiva lead i mali tim. S leadom razgovaraš, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim prolazi kroz kartice po prioritetu, koristeći jednostavnu naredbenu liniju napravljenu za jezične modele. Prije nego išta stigne natrag do tebe, AI tester prati korake u kopiji aplikacije i prilaže snimku zaslona. Gotov posao stiže na tvoju hrpu s promijenjenim datotekama i diffom. Prihvatiš ga ili ostaviš komentar, pa se tim probudi i pokuša ponovno. Samo ti možeš premjestiti karticu u Gotovo.","Otprilike ovako izgleda dan s AI-gileom. Navečer ostaviš nekoliko komentara: ovaj je gumb na krivom mjestu, taj popis treba sortirati, može li tamna tema. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako stupac Na redu presuši, noćni čuvar ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobati, svaka s koracima koje može pratiti pospana osoba i snimkom zaslona na kojoj radi. Pregledaš ih klikom, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje koliko je sve to potrošilo, a način bez tokena tu je za štedljive tjedne. Zatim doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, što AI-gile nije. Nije startup, nije na prodaju i nitko ne prikuplja tvoje podatke. To je besplatna ploča koja radi na tvom računalu, bez računa, bez tragača i bez kolačića. Što jest: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji rade kartice i tobom koji donosiš odluke. Spaja povezane kartice, ispravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od nizozemskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu slati poruke jedni drugima, privatno i šifrirano. Izgradili su ga Rich i velik broj strpljivih agenata, uglavnom koristeći sam program. U zatvorenoj je pre-alfi, pa je mjestimice grub. Ako ti zvuči zabavno, lijepo zamoli i možda uđeš rano."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Duljine su, usput, story pointovi. Naravno da jesu.","55":"Pedeset i pet riječi. Dok si čitao, dvije su kartice završene.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan redak koda.","first-board.name":"Prva ploča","first-board.line":"Ploča koja prati vlastitu izgradnju: kartice, stupci, povuci i ispusti, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, predlošci timova, prostori i tko što radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unatrag.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri što pokretanja koštaju, drži kod vitkim, štedi svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, pomiješani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na zaslonu u jezičnoj datoteci, prvo nizozemski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku primopredaju i pokazuje što je vidio.","website.name":"Web-stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Chat i streaming","streaming.line":"Discord, Twitch, OBS, streamerski način, GIF-ovi i emojiji.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Ploča za ljude koji programiraju bez AI-ja i javne ploče.","night-watch.name":"Noćni čuvar","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Mobitel i Android","p-android.line":"Dođi do ploče s mobitela, a zatim prava Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, stranica uživo, zatim beta.","p-languages.name":"Još jezika","p-languages.line":"Više od sto jezika i način uranjanja za one koji uče.","p-engines.name":"Još AI motora","p-engines.line":"Odaberi Claude, Codex ili Gemini za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, merge vrata, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Način za umorne, podsjetnici za brigu o sebi i 4:20.","p-servers.name":"Poslužitelji i rast","p-servers.line":"Globalne postavke poslužitelja, uloge i planiranje rasta.","p-livestream.name":"Streaming dodaci","p-livestream.line":"Twitch chat, vlastiti emojiji i javni prikaz uživo."},"words":{"button":"📖 Programerske riječi","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Traži riječ…","none":"Nijedna riječ ne odgovara.","close":"Zatvori","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mapa projekta s kodom i cijelom poviješću commitova, obično pohranjena i na GitHubu.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se izmjene mogu raditi bez diranja glavne verzije.","also":["branchevi","grana","grane","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Spremljena snimka koda s kratkom bilješkom o tome što se promijenilo. Uvijek se možeš vratiti na neku.","also":["commitovi","commita","commitu","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje spremljenih snimki (commitova) s ovog računala na GitHub, da budu sigurnosno kopirane i podijeljene."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje izmjena iz brancha natrag u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Zahtjev da se izmjene iz brancha provjere i spoje u glavnu verziju.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoriranje","text":"Uređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasniji nazivi, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi onako kako bi trebalo.","also":["bugovi","buga","bugu","bugs"]},{"id":"test","g":"build","word":"Test","text":"Isprobavanje gotovog posla da se provjeri radi li ono što je traženo, prije nego ga prihvatiš.","also":["testovi","testirati","testiranje","testiraš","testiraj","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Puštanje nove verzije uživo, na primjer na poslužitelj na kojem je ljudi koriste."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideje i posao koji još nisu uvršteni u plan. Na njima se ništa ne radi dok se ne premjeste u stupac Na redu."},{"id":"sprint","g":"team","word":"Sprint","text":"Kratko razdoblje rada (često tjedan ili dva) s dogovorenim skupom kartica koje treba završiti.","also":["sprintovi","sprinta","sprintu","sprintom","sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Brza provjera: što je svaki član tima napravio, što radi dalje i što ga koči.","also":["standup","stand-upovi","stand-upa","stand-upu","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ploča sa stupcima (Na redu, U tijeku, Gotovo) na kojoj se kartice kreću slijeva nadesno kako posao napreduje."},{"id":"wip","g":"team","word":"WIP ograničenje","text":"Work in progress, tj. posao u tijeku: najviše kartica koje stupac smije sadržavati, da tim završi stvari prije nego započne nove.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI koji samostalno radi na zadatku: čita kod, mijenja ga, pokreće provjere i javlja natrag.","also":["agenti","agenta","agentu","agents"]},{"id":"token","g":"team","word":"Token","text":"Jedinica u kojoj se broji AI potrošnja: otprilike nekoliko slova pročitanog ili napisanog teksta. Manje tokena, više paketa ostaje.","also":["tokeni","tokena","tokenu","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Mala naredba koja se sama pokreće u zadanom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooka","hookove","hook","hooks"]}]}};
